// These are exact raw original witnesses, not screenshots generated by Wordling.
// Compare named text/status fragments and semantic gap/cursor relationships;
// differing raster/row/layout geometry is explicitly outside this bounded test.
func originalCue(t *testing.T, branch, label, cue string) {
	t.Helper()
	type fact struct {
		Screen string `json:"screen_path"`
		SHA    string `json:"screen_sha256"`
	}
	var index struct {
		Branches map[string]struct {
			States map[string][]fact `json:"states"`
		} `json:"branches"`
	}
	b, e := os.ReadFile("../../docs/research/continuation/session1/state-index.json")
	if e != nil {
		t.Fatal(e)
	}
	if e = json.Unmarshal(b, &index); e != nil {
		t.Fatal(e)
	}
	facts := index.Branches[branch].States[label]
	if len(facts) != 2 {
		t.Fatalf("missing fresh pair %s/%s", branch, label)
	}
	for _, f := range facts {
		raw, e := os.ReadFile("../../" + f.Screen)
		if e != nil {
			t.Fatal(e)
		}
		sum := sha256.Sum256(raw)
		if hex.EncodeToString(sum[:]) != f.SHA || !strings.Contains(string(raw), cue) {
			t.Fatalf("original witness mismatch %s %q", f.Screen, cue)
		}
		t.Logf("original %s sha256=%s cue=%q", f.Screen, f.SHA, cue)
	}
}
func TestComposedOriginalCursorAndExitStates(t *testing.T) {
	_, m, b, _ := testModel(t)
	m = retrieve(m)
	m, _ = press(m, tea.KeyF3, tea.ModAlt, "")
	if !strings.Contains(ansi.Strip(m.View().Content), "A[BOLD]BC[bold]D") {
		t.Fatal("Reveal missing shared projection")
	}
	m, _ = press(m, tea.KeyRight, 0, "")
	first := m.View().Cursor.X
	originalCue(t, "cursor", "codes-gap-1", "A[BOLD]BC[bold]D")
	originalCue(t, "cursor", "codes-gap-1", "Press Reveal Codes to restore screen")
	m, _ = press(m, tea.KeyRight, 0, "")
	if m.Session().Snapshot().Gap != 2 || m.View().Cursor.X != first {
		t.Fatal("code movement changed visible text position")
	}
	originalCue(t, "cursor", "codes-gap-2", "A[BOLD]BC[bold]D")
	m, _ = press(m, tea.KeyF7, 0, "")
	for _, cue := range []string{"Save document? Yes (No)", "(Text was not modified)"} {
		originalCue(t, "named-unchanged-quit", "exit-save-question", cue)
		if !strings.Contains(m.View().Content, cue) {
			t.Fatal("missing exact original status", cue)
		}
	}
	m, _ = press(m, tea.KeyF1, 0, "")
	if m.Session().Snapshot().Mode != editor.Editing || m.Session().Snapshot().Gap != 2 {
		t.Fatal("F1 did not retain")
	}
	got, _ := m.Session().Document().Export()
	if string(got) != string(b) {
		t.Fatal("F1 changed native")
	}
	m, _ = press(m, tea.KeyF7, 0, "")
	m, _ = press(m, 'n', 0, "n")
	for _, cue := range []string{"Exit WP? No (Yes)", "(Cancel to return to document)"} {
		originalCue(t, "named-unchanged-quit", "exit-application-question", cue)
		if !strings.Contains(m.View().Content, cue) {
			t.Fatal("exit cue", cue)
		}
	}
	m, c := press(m, 'y', 0, "y")
	if c == nil || m.Session().Snapshot().Mode != editor.Exited {
		t.Fatal("original exit did not produce Quit")
	}
	originalCue(t, "named-unchanged-quit", "exit-dos-result", "C:\\WP51>")
	// Domain Exited and restored Linux terminal correspond to exit, not a fake DOS shell.
}
func TestFailedUncertainResultKeepsNativeAndNeverExits(t *testing.T) {
	_, m, b, _ := testModel(t)
	m = retrieve(m)
	m, _ = press(m, tea.KeyF10, 0, "")
	m, _ = press(m, 'C', 0, "COPY")
	m, c := press(m, tea.KeyEnter, 0, "")
	n, _ := m.Update(c())
	m = n.(Model)
	p := m.Session().Snapshot().Pending
	f := &storage.Failure{Kind: storage.PublicationUncertain, Stage: "injected host receipt", Name: "COPY", Candidate: ".wordling-candidate-test", DestinationMayExist: true}
	n, _ = m.Update(resultMsg{editor.Result{Operation: p.Operation, Revision: p.Revision, Kind: p.Kind, Err: f}})
	m = n.(Model)
	if m.Session().Snapshot().SaveState != editor.SaveUncertain || m.State().Reconciliation == "" {
		t.Fatal("uncertainty suppressed")
	}
	f.Candidate = "mutated"
	if strings.Contains(m.State().Reconciliation, "mutated") {
		t.Fatal("receipt aliased")
	}
	m, _ = press(m, tea.KeyF7, 0, "")
	if m.Session().Snapshot().Mode == editor.ExitSaveQuestion {
		t.Fatal("uncertainty permitted exit")
	}
	got, _ := m.Session().Document().Export()
	if string(got) != string(b) {
		t.Fatal("uncertain receipt changed native")
	}
}
func TestPrintableShiftAndCapsAndOpaqueWindow(t *testing.T) {
	_, m, _, _ := testModel(t)
	m, _ = press(m, tea.KeyF10, tea.ModShift, "")
	m, _ = press(m, 'o', tea.ModShift, "ORIGIN")
	m, c := press(m, tea.KeyEnter, 0, "")
	m = drain(m, c)
	if m.Session().Snapshot().Name != "ORIGIN" {
		t.Fatal("uppercase actual transport text refused")
	}
	if !strings.Contains(ansi.Strip(m.View().Content), "ABCD") {
		t.Fatal("normal shared projection missing")
	}
	for _, size := range []tea.WindowSizeMsg{{Width: 1, Height: 1}, {Width: 0, Height: 0}, {Width: 1000000000, Height: 1000000000}} {
		n, _ := m.Update(size)
		v := n.(Model).View()
		if v.Content == "" {
			t.Fatal("resize lost explicit content")
		}
	}
}
